launch_scripts.baselines/launch_e10_evoskill.sh:
#!/usr/bin/env bash
# launch_e10_evoskill.sh <seed>
S=$1; B=/home/dev/projects2/campaign-scratch/baselines
O=/home/dev/projects2/campaign-scratch/runs/E10/evoskill/s$S; mkdir -p $O
source /home/dev/projects2/campaign-scratch/bench/local/env_local.sh
export BL_REWARD_METRIC=hard_restriction KERNEL_TIMEOUT_S=600   # search-phase parity (see KERNEL_TIMEOUT_CHANGE.txt)
exec /home/dev/projects2/campaign-scratch/bench/venv/bin/python -I -u $B/code/evoskill_run.py --out $O --seed $S \
  --tag-prefix E10-evoskill-s$S --max-iterations 12 --max-rollouts 600 --concurrency 4 ${EVO_CONTINUE:+--continue}

